package glitch

import data.glitch_lib

# Credential-related keywords for matching in names
cred_keywords := {"password", "passwd", "pwd", "secret", "token", "key", "api_key", "apikey", "access_key", "secret_key", "private_key", "credential", "auth_token", "sha512_password"}

# Weak/default passwords
weak_passwords := {"admin", "password", "123456", "default", "changeme", "guest", "user", "login", "qwerty", "letmein", "welcome", "telarista"}

# Check if string contains a credential keyword
contains_cred_keyword(s) {
    lower_s := lower(s)
    kw := cred_keywords[_]
    contains(lower_s, kw)
}

# Check if value looks like a hardcoded secret
is_hardcoded_secret(val) {
    val.ir_type == "String"
    count(val.value) > 0
    not looks_like_reference(val.value)
}

# Check for weak/common passwords
is_weak_password(val) {
    val.ir_type == "String"
    lower_val := lower(val.value)
    weak_pw := weak_passwords[_]
    lower_val == weak_pw
}

# Check if string looks like a variable reference or function call
looks_like_reference(s) {
    regex.match("^\\$\\{.*\\}$", s)
} else {
    regex.match("^vault::", s)
} else {
    regex.match("^\\${?\\w+", s)
} else {
    regex.match("^!\\w+", s)
}

# Walk through Hash structure to find credential keys with hardcoded values
find_credential_in_hash(obj) = results {
    obj.ir_type == "Hash"
    results := [r |
        some i
        r := check_hash_entry(obj.value[i])
    ]
} else = [] {
    true
}

check_hash_entry(entry) = result {
    entry.key.ir_type == "String"
    entry.value.ir_type == "String"
    contains_cred_keyword(entry.key.value)
    is_hardcoded_secret(entry.value)
    result := {
        "key": entry.key.value,
        "value": entry.value,
        "found": true
    }
} else = result {
    entry.key.ir_type == "String"
    entry.value.ir_type == "Hash"
    nested := find_credential_in_hash(entry.value)
    count(nested) > 0
    result := {
        "key": entry.key.value,
        "nested": nested[_],
        "found": true
    }
} else = {"found": false} {
    true
}

# Extract actual element with line info for reporting
get_element_for_report(var_or_attr, hash_result) = elem {
    hash_result.nested
    elem := hash_result.nested.value
} else = elem {
    hash_result.key
    elem := var_or_attr.value
} else = elem {
    elem := var_or_attr.value
}

# Main detection: Variables with credential keywords in name and hardcoded string value
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Variable name contains credential keyword
    contains_cred_keyword(var.name)

    # Value is a hardcoded string (not Hash/Array)
    var.value.ir_type == "String"
    is_hardcoded_secret(var.value)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": sprintf("Use of Hard-coded Credentials - Variable '%s' contains hardcoded credential. Use secret management systems instead. (CWE-798)", [var.name])
    }
}

# Main detection: Variables with Hash values containing credential keys
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Variable Hash value contains nested credential keys
    var.value.ir_type == "Hash"

    # Recursively check for credential keys with hardcoded values
    hash_result := check_hash_entry(var.value.value[_])
    hash_result.found == true

    elem := get_element_for_report(var, hash_result)

    result := {
        "type": "sec_hard_secr",
        "element": elem,
        "path": parent.path,
        "description": sprintf("Use of Hard-coded Credentials - Hardcoded value found for credential key in '%s'. Use secret management systems instead. (CWE-798)", [var.name])
    }
}

# Detection: Atomic unit attributes with credential keywords
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    aus := glitch_lib.all_atomic_units(parent)
    au := aus[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Attribute name contains credential keyword
    contains_cred_keyword(attr.name)

    # Direct string value
    attr.value.ir_type == "String"
    is_hardcoded_secret(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": sprintf("Use of Hard-coded Credentials - Attribute '%s' in '%s' contains hardcoded credential. Use secret management systems instead. (CWE-798)", [attr.name, au.type])
    }
}

# Detection: Nested credential keys in atomic unit Hash attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    aus := glitch_lib.all_atomic_units(parent)
    au := aus[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Hash attribute contains nested credential keys
    attr.value.ir_type == "Hash"

    hash_result := check_hash_entry(attr.value.value[_])
