    elem := get_element_for_report(attr, hash_result)

    result := {
        "type": "sec_hard_secr",
        "element": elem,
        "path": parent.path,
        "description": sprintf("Use of Hard-coded Credentials - Hardcoded value found for credential key in attribute '%s' of '%s'. Use secret management systems instead. (CWE-798)", [attr.name, au.type])
    }
}

# Detection: Weak/default password values anywhere
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
